import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.ContainerSetData{WindowID: 5, Key: 1, Value: 200}
PLAIN = bytes.fromhex("05029003")

# generated by gophertunnel b8bd735:
# packet.ContainerSetData{WindowID: 0xff, Key: 4, Value: -1}
NONE = bytes.fromhex("ff0801")

# generated by gophertunnel b8bd735:
# packet.ContainerSetData{WindowID: 0, Key: -1, Value: 300}
WIDE = bytes.fromhex("0001d804")

GOLDENS = [
    pytest.param(v2225.ContainerSetDataPacket(container_id=5, id=1, value=200), PLAIN, id="plain"),
    pytest.param(
        v2225.ContainerSetDataPacket(container_id=v2225.ContainerID.NONE, id=4, value=-1),
        NONE,
        id="none-container-negative-value",
    ),
    pytest.param(
        v2225.ContainerSetDataPacket(container_id=v2225.ContainerID.INVENTORY, id=-1, value=300),
        WIDE,
        id="negative-id-wide-value",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_set_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_set_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
